from document_client import get_openai_client
from document_models import ExtractedInvoice, LineItem
import json
from datetime import date

def extract_invoice_fields(invoice_image_base64: str) -> ExtractedInvoice:
    client = get_openai_client()

    prompt = """You are an expert at extracting structured data from invoices. 
               Extract the vendor name, invoice date (YYYY-MM-DD), total amount, and line items (description, quantity, unit_price, total) from the provided invoice image. 
               Return the data as a JSON object strictly conforming to the following Pydantic model:
               {
                   "vendor": "string",
                   "date": "YYYY-MM-DD string",
                   "total": "float",
                   "line_items": [
                       {
                           "description": "string",
                           "quantity": "float",
                           "unit_price": "float",
                           "total": "float"
                       }
                   ]
               }
               If a field is not found, use a reasonable default or omit it if optional.
               The invoice image is provided in base64 format.
            """

    response = client.chat.completions.create(
        model="gpt-4o", # Concrete model identifier
        messages=[
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {
                        "type": "image_url",
                        "image_url": {"url": f"data:image/jpeg;base64,{invoice_image_base64}"}
                    }
                ]
            }
        ],
        response_format={ "type": "json_object" },
        temperature=0.0
    )

    extracted_data = json.loads(response.choices[0].message.content)

    # Convert date string to date object
    if 'date' in extracted_data and isinstance(extracted_data['date'], str):
        extracted_data['date'] = date.fromisoformat(extracted_data['date'])

    # Convert line items to LineItem objects if present
    line_items = []
    if 'line_items' in extracted_data and isinstance(extracted_data['line_items'], list):
        for item_data in extracted_data['line_items']:
            line_items.append(LineItem(**item_data))
    extracted_data['line_items'] = line_items

    return ExtractedInvoice(**extracted_data)

import os
from document_client import get_documentai_client
from document_models import ExtractedReceipt
from typing import Dict, Any, List

def extract_receipt_fields(file_content: bytes, mime_type: str) -> ExtractedReceipt:
    client = get_documentai_client()

    project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
    location = os.getenv("GOOGLE_CLOUD_LOCATION", "us") # e.g., "us" or "eu"
    processor_id = os.getenv("DOCUMENTAI_RECEIPT_PROCESSOR_ID") # Specific Document AI processor for receipts

    if not project_id or not processor_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT and DOCUMENTAI_RECEIPT_PROCESSOR_ID environment variables must be set.")

    name = client.processor_path(project_id, location, processor_id)

    # Read the file into memory.
    document = documentai.RawDocument(
        content=file_content,
        mime_type=mime_type # e.g., "application/pdf", "image/jpeg", "image/png"
    )

    # Configure the process request.
    request = documentai.ProcessRequest(
        name=name,
        raw_document=document,
    )

    result = client.process_document(request=request)
    document_response = result.document

    merchant_name = ""
    total_amount = 0.0
    tax_amount = None
    items: List[Dict[str, Any]] = []

    for entity in document_response.entities:
        if entity.type == "merchant_name":
            merchant_name = entity.mention_text
        elif entity.type == "total_amount":
            try:
                total_amount = float(entity.mention_text)
            except ValueError:
                pass
        elif entity.type == "tax_amount":
            try:
                tax_amount = float(entity.mention_text)
            except ValueError:
                pass
        elif entity.type == "line_item":
            item_data = {}
            for prop in entity.properties:
                if prop.type == "description":
                    item_data["description"] = prop.mention_text
                elif prop.type == "price":
                    try:
                        item_data["price"] = float(prop.mention_text)
                    except ValueError:
                        pass
            if item_data: # Only add if some data was extracted for the item
                items.append(item_data)

    return ExtractedReceipt(
        merchant=merchant_name,
        total=total_amount,
        tax=tax_amount,
        items=items
    )

from document_client import get_anthropic_client
from document_models import ExtractedInvoice

def summarize_invoice_fields(invoice: ExtractedInvoice) -> str:
    client = get_anthropic_client()

    prompt = f"""Please summarize the key details of the following invoice in a concise paragraph. 
               Include the vendor, date, total amount, and a brief mention of the line items. 
               Do not include any conversational filler.

               Invoice details:
               Vendor: {invoice.vendor}
               Date: {invoice.date}
               Total: {invoice.total}
               Line Items: {', '.join([item.description for item in invoice.line_items]) if invoice.line_items else 'N/A'}
            """

    response = client.messages.create(
        model="claude-3-opus-20240229", # Concrete model identifier
        max_tokens=200,
        messages=[
            {"role": "user", "content": prompt}
        ]
    )

    return response.content[0].text
